<!-- wp:wdl/lw-qa-1 {"mainColor":"#834a1f","fontWeightDt":"600"} -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:600">機種を変えたらどうなりますか</p></div><div class="open_icon" style="background:#834a1f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#834a1f">A<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">同じアカウントで入り直していただければ、スタンプはそのまま残ります。分からなくなったときは、レジでお声がけください。こちらでお調べします。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:600">アプリは要りますか</p></div><div class="open_icon" style="background:#834a1f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#834a1f">A<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">要りません。お手持ちのメッセージアプリの中で完結します。新しく何かを入れていただく必要はありません。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:600">やめられますか</p></div><div class="open_icon" style="background:#834a1f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#834a1f">A<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">いつでもご自分でやめられます。お店にお知らせいただく必要もありません。やめたあとにこちらからご連絡することもありません。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:600">紙のカードはどうなりますか</p></div><div class="open_icon" style="background:#834a1f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#834a1f">A<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">お持ちの紙のカードは、そのままお使いいただけます。レジでお申し出いただければ、たまっている数をスマホのほうへ移します。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:600">家族で分けられますか</p></div><div class="open_icon" style="background:#834a1f"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#834a1f">A<div style="background:#834a1f"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">恐れ入りますが、1台につき1つです。ご家族それぞれで登録していただくと、それぞれにたまります。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
